function moveRobot(grid, position, command) {
  if (!Array.isArray(grid) || grid.length === 0) {
    throw new TypeError('grid must be non-empty');
  }

  let columns;
  for (let rowIndex = 0; rowIndex < grid.length; rowIndex += 1) {
    const row = grid[rowIndex];
    if (!Array.isArray(row) || row.length === 0) {
      throw new TypeError('invalid grid');
    }
    if (columns === undefined) columns = row.length;
    if (row.length !== columns) {
      throw new TypeError('invalid grid');
    }
    for (let columnIndex = 0; columnIndex < columns; columnIndex += 1) {
      if (row[columnIndex] !== 0 && row[columnIndex] !== 1) {
        throw new TypeError('invalid grid');
      }
    }
  }

  if (position === null || typeof position !== 'object' || Array.isArray(position)) {
    throw new TypeError('invalid position');
  }
  const prototype = Object.getPrototypeOf(position);
  if ((prototype !== Object.prototype && prototype !== null) ||
      !Number.isInteger(position.row) || !Number.isInteger(position.column) ||
      position.row < 0 || position.row >= grid.length ||
      position.column < 0 || position.column >= columns ||
      grid[position.row][position.column] !== 0) {
    throw new TypeError('invalid position');
  }

  const deltas = { N: [-1, 0], S: [1, 0], E: [0, -1], W: [0, 1] };
  if (!Object.prototype.hasOwnProperty.call(deltas, command)) {
    throw new TypeError('invalid command');
  }

  const nextRow = position.row + deltas[command][0];
  const nextColumn = position.column + deltas[command][1];
  if (nextRow < 0 || nextRow >= grid.length ||
      nextColumn < 0 || nextColumn >= columns ||
      grid[nextRow][nextColumn] === 1) {
    return { row: position.row, column: position.column };
  }
  return { row: nextRow, column: nextColumn };
}

module.exports = { moveRobot };

