'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['moveRobot']);
const { moveRobot } = api;

const grid = [
  [0, 0, 1],
  [1, 0, 0],
  [0, 0, 0]
];
assert.deepStrictEqual(moveRobot(grid, { row: 1, column: 1 }, 'N'), { row: 0, column: 1 });
assert.deepStrictEqual(moveRobot(grid, { row: 1, column: 1 }, 'E'), { row: 1, column: 2 });
assert.deepStrictEqual(moveRobot(grid, { row: 1, column: 1 }, 'W'), { row: 1, column: 1 });
assert.deepStrictEqual(moveRobot(grid, { row: 0, column: 0 }, 'N'), { row: 0, column: 0 });
assert.deepStrictEqual(moveRobot([[0]], { row: 0, column: 0 }, 'S'), { row: 0, column: 0 });

const position = { row: 1, column: 1, ignored: true };
const gridBefore = grid.map((row) => row.slice());
const positionBefore = { ...position };
const stopped = moveRobot(grid, position, 'W');
assert.deepStrictEqual(stopped, { row: 1, column: 1 });
assert.deepStrictEqual(Object.keys(stopped), ['row', 'column']);
assert.notStrictEqual(stopped, position);
assert.deepStrictEqual(grid, gridBefore);
assert.deepStrictEqual(position, positionBefore);

for (const badGrid of [null, {}, [], [0], [[]], [[0], [0, 1]], [[0, 2]], [[0, false]], [[0], null]]) {
  assert.throws(() => moveRobot(badGrid, { row: 0, column: 0 }, 'E'), TypeError);
}
const sparseGrid = [[0, 0]];
delete sparseGrid[0][1];
assert.throws(() => moveRobot(sparseGrid, { row: 0, column: 0 }, 'W'), TypeError);
const sparseRows = new Array(1);
assert.throws(() => moveRobot(sparseRows, { row: 0, column: 0 }, 'N'), TypeError);

for (const badPosition of [null, [], new Date(), {}, { row: 0 }, { column: 0 }, { row: 0.5, column: 0 }, { row: 0, column: '0' }, { row: -1, column: 0 }, { row: 0, column: 3 }, { row: 0, column: 2 }]) {
  assert.throws(() => moveRobot(grid, badPosition, 'E'), TypeError);
}
for (const badCommand of ['n', 'NE', '', null, undefined, 1]) {
  assert.throws(() => moveRobot(grid, { row: 0, column: 0 }, badCommand), TypeError);
}
assert.throws(
  () => moveRobot([[0, 0], [0, 7]], { row: 0, column: 0 }, 'N'),
  TypeError
);

